<style>.ca-page{color:#203346}.ca-head{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:20px}.ca-head p{margin:4px 0 0;color:#748390;font-size:13px}.ca-head h3,.ca-head h4{margin:0;font-weight:700}.ca-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:18px}.ca-stats>div{background:white;border:1px solid #dce6ee;border-radius:10px;padding:18px}.ca-stats small,.ca-stats strong{display:block}.ca-stats strong{font-size:23px;margin-top:5px}.ca-stats>div:last-child{background:#ecf7f1}#ca-dialog{width:min(700px,94vw);border:0;border-radius:12px;padding:24px;max-height:92dvh;overflow:auto}#ca-dialog::backdrop{background:#142d466b}@media(max-width:600px){.ca-stats{grid-template-columns:1fr}.ca-head{align-items:flex-start}}.ca-week-tabs{display:flex;gap:8px;flex-wrap:wrap}.ca-person{background:white;border:1px solid #dce6ee;margin-bottom:12px;padding:16px}.ca-person-head{display:flex;align-items:center;justify-content:space-between;gap:14px}.ca-week-summary{display:flex;gap:18px;flex-wrap:wrap;margin:14px 0;font-size:13px}.ca-person summary{cursor:pointer;font-size:13px;color:#456}.ca-week-tabs .active{background:#203346;color:white}@media(max-width:600px){.ca-person-head{flex-wrap:wrap}}</style>
<script>
(function(){const dialog=document.getElementById('ca-dialog'),form=document.getElementById('ca-form'),rows={{ \Illuminate\Support\Js::from($editRows) }},store={{ \Illuminate\Support\Js::from(route('contractor-advances.store')) }};
document.getElementById('ca-add').addEventListener('click',()=>{form.reset();form.action=store;form.elements._method.value='POST';document.getElementById('ca-title').textContent='Add Contractor Advance';dialog.showModal();});document.getElementById('ca-close').addEventListener('click',()=>dialog.close());document.querySelectorAll('[data-ca-edit]').forEach(button=>button.addEventListener('click',()=>{const row=rows.find(r=>String(r.id)===button.dataset.caEdit);form.reset();for(const [key,value] of Object.entries(row))if(form.elements.namedItem(key))form.elements.namedItem(key).value=value??'';form.action=store+'/'+row.id;form.elements._method.value='PUT';document.getElementById('ca-title').textContent='Edit Contractor Advance';dialog.showModal();}));let selectedWeek={{ \Illuminate\Support\Js::from($week?(string)$week:'') }};
function refresh(){const q=document.getElementById('ca-search').value.toLowerCase().trim();let total=0;document.querySelectorAll('.ca-person').forEach(person=>{const amounts=JSON.parse(person.dataset.weekAmounts),amount=Object.entries(amounts).reduce((sum,[w,n])=>sum+(!selectedWeek||w===selectedWeek?Number(n):0),0);person.hidden=!person.dataset.caName.includes(q);if(!person.hidden)total+=amount;person.querySelector('.ca-person-total').textContent='Rs '+(amount/100).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});let count=0;person.querySelectorAll('tr[data-week]').forEach(row=>{row.hidden=!!selectedWeek&&row.dataset.week!==selectedWeek;if(!row.hidden)count++;});person.querySelector('.ca-empty').hidden=count>0;person.querySelectorAll('[data-week-summary]').forEach(el=>el.hidden=!!selectedWeek&&el.dataset.weekSummary!==selectedWeek);});document.getElementById('ca-visible-total').textContent='Visible advances: Rs '+(total/100).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});document.querySelectorAll('[data-week-filter]').forEach(btn=>btn.classList.toggle('active',btn.dataset.weekFilter===selectedWeek));}
document.querySelectorAll('[data-week-filter]').forEach(btn=>btn.addEventListener('click',()=>{selectedWeek=btn.dataset.weekFilter;const url=new URL(location.href);url.searchParams.set('month',{{ \Illuminate\Support\Js::from($month->format('Y-m')) }});selectedWeek?url.searchParams.set('week',selectedWeek):url.searchParams.delete('week');history.replaceState(null,'',url);refresh();}));
document.getElementById('ca-search').addEventListener('input',refresh);
document.getElementById('ca-month-form').addEventListener('change',function(){this.requestSubmit();});
document.querySelectorAll('[data-ca-add-person]').forEach(btn=>btn.addEventListener('click',()=>{document.getElementById('ca-add').click();form.elements.contractor_id.value=btn.dataset.caAddPerson;if(selectedWeek){const base={{ \Illuminate\Support\Js::from($month->format('Y-m')) }}+'-'+String((Number(selectedWeek)-1)*7+1).padStart(2,'0');if(base<=form.elements.advance_date.max)form.elements.advance_date.value=base;}updateWeek();}));
const weekInfo=document.createElement('small');weekInfo.className='text-muted d-block mt-1';form.elements.advance_date.after(weekInfo);function updateWeek(){const date=form.elements.advance_date.value;weekInfo.textContent=date?'Payment month: '+date.slice(0,7)+' · Week '+Math.ceil(Number(date.slice(8,10))/7):'';}form.elements.advance_date.addEventListener('change',updateWeek);document.getElementById('ca-add').addEventListener('click',updateWeek);refresh();updateWeek();
document.querySelectorAll('[data-ca-edit]').forEach(btn=>btn.addEventListener('click',updateWeek));
@if($errors->any()) dialog.showModal(); @endif
form.addEventListener('submit',()=>{form.querySelector('button[type=submit]').disabled=true;});})();
</script>
